        if (responseMsg.type === 'SYNC_RESPONSE' && responseMsg.payload) {
            const syncPayload = responseMsg.payload as SyncResponse<E>;
            let caughtUpCount = 0;

            if (syncPayload.blocks.length > 0 && syncPayload.blocks[0].sequence > nextSeq) {
