            const orderMap = new Map<string, number>();
            this.replayInterleaves.forEach((id, idx) => orderMap.set(id, idx));

            this.queue.sort((a, b) => {
                const idxA = orderMap.get(a.taskId)!;
                const idxB = orderMap.get(b.taskId)!;
